// Author: MiYu. Minimal altar revival lifecycle check across pricing, existing hero identity, refunds and script contexts.
#include "session.h"
#include "setup.h"
#include "player_commands.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=3 && argc!=4)throw std::runtime_error("Usage: war3_revival_tests <data-root> <fixture> [awaken]");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto value=[&](const char* name){return vm.global(name).bits;};auto hero=vm.global("hero"),altar=vm.global("altar"),backup=vm.global("backup");auto identity=session.units().at(hero.bits);auto experience=identity->experience,skills=identity->skillPoints;auto abilities=identity->abilities;auto inventory=identity->inventory;auto properName=identity->properName;auto gold=[&]{return session.config().players[0].states.at(1);};auto food=[&]{return session.config().players[0].states.at(5);};unsigned passed=0;
        if(argc==4){if(std::wstring(argv[3])!=L"awaken")throw std::runtime_error("Unknown revival test mode");auto player=call("Player",{vm.integer(0)}),neutral=call("Player",{vm.integer(15)});auto coordinate=[&](int n){return vm.real(jass::Real::fromInteger(n));};auto tavern=call("CreateUnit",{neutral,vm.integer(int(ObjectData::code("ntav"))),coordinate(256),coordinate(256),coordinate(0)});auto buyer=call("CreateUnit",{player,vm.integer(int(ObjectData::code("hpea"))),coordinate(256),coordinate(384),coordinate(0)});require(session.units().contains(tavern.bits) && session.units().contains(buyer.bits),"Unable to create tavern and shopper");call("SetPlayerState",{player,vm.handle("playerstate",1),vm.integer(5000)});call("InstallAwakenTest",{tavern});call("SetAwakenTestMode",{vm.integer(1)});call("KillUnit",{hero});auto beforeGold=gold(),beforeLumber=session.config().players[0].states.at(2);auto buttons=session.commands(tavern.bits,0);auto button=std::find_if(buttons.begin(),buttons.end(),[&](auto& item){return item.action==CommandAction::Awaken && item.type==hero.bits;});require(button!=buttons.end() && button->enabled && button->x==0 && button->y==0 && button->gold==510 && button->lumber==120,"Awaken button, cost or eligibility incorrect");PlayerCommand command;command.player=0;command.kind=PlayerCommandKind::Awaken;command.units={tavern.bits};command.objectType=hero.bits;require(dispatchPlayerCommand(session,command)==1,"Awaken command failed");require(session.units().at(hero.bits)==identity && identity->experience==experience && identity->abilities==abilities && identity->inventory==inventory && identity->properName==properName && std::abs(std::bit_cast<float>(identity->life.bits())-std::bit_cast<float>(identity->maxLife.bits())*.5f)<.01f && std::bit_cast<float>(identity->mana.bits())==0 && gold()==beforeGold-510 && session.config().players[0].states.at(2)==beforeLumber-120 && food()==6 && value("finished")==1 && value("awakenCalls")==1 && !value("awakenNested"),"Awaken did not preserve hero, price, population, restore state, finish event or reject recursion");call("KillUnit",{hero});call("SetAwakenTestMode",{vm.integer(2)});beforeGold=gold();beforeLumber=session.config().players[0].states.at(2);require(dispatchPlayerCommand(session,command)==0 && gold()==beforeGold && session.config().players[0].states.at(2)==beforeLumber && identity->level==4 && std::bit_cast<float>(identity->life.bits())<=0 && value("awakenCalls")==2,"Awaken did not refund after order callback changed hero price");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS tavern_awaken_identity_cost_and_reentry\nRESULT passed=1 failed=0\n";return 0;}
        call("KillUnit",{hero});require(value("revivable")==1 && food()==0,"Dead hero did not become revivable or release current food");auto price=session.revivalInfo(hero.bits);require(price.gold==255 && price.lumber==0 && price.trainTime>0 && price.trainTime<.25f,"Source level-three revival price/time differs");auto buttons=session.commands(altar.bits,0);require(std::any_of(buttons.begin(),buttons.end(),[&](auto& button){return button.action==CommandAction::Revive && button.type==hero.bits && button.enabled && !button.icon.empty();}),"Dead hero has no real altar command");session.startAI(0,"revival.ai");auto& ai=*session.ais()[0]->runtime;auto aiCall=[&](const char* name,std::initializer_list<jass::Value> args){return ai.invoke(name,{args.begin(),args.size()});};require(aiCall("SetProduce",{ai.integer(1),ai.integer(int(identity->type)),ai.integer(-1)}).bits && !session.targetOrder(backup.bits,hero.bits,852039),"Revive order or duplicate queue ownership failed");auto p0=call("Player",{vm.integer(0)});require(call("GetPlayerTechCount",{p0,vm.integer(int(identity->type)),vm.boolean(true)}).bits==1,"Revival counted the existing hero twice in technology limits");require(gold()==745 && food()==5 && value("started")==1,"Revival did not pay, reserve food or dispatch start");session.advance(.25);require(session.units().at(hero.bits)==identity && std::bit_cast<float>(identity->life.bits())>0 && identity->experience==experience && identity->abilities==abilities && identity->skillPoints==skills && identity->inventory==inventory && identity->properName==properName,"Altar replaced the hero or lost progression/items");require(value("finished")==1 && !identity->revivalBuilding && session.units().at(altar.bits)->production.empty() && food()==5,"Completion failed to release queue/food state");require(std::bit_cast<float>(identity->life.bits())<std::bit_cast<float>(identity->maxLife.bits())*.51f && std::bit_cast<float>(identity->mana.bits())<std::bit_cast<float>(identity->maxMana.bits())*.26f && !session.effects().empty(),"Source revive fractions or actual visual instance were ignored");++passed;std::cout<<"PASS paid_altar_identity_and_events\n";
        call("KillUnit",{hero});auto before=gold();require(session.targetOrder(altar.bits,hero.bits,852039),"Unable to queue cancellation case");require(session.cancelProduction(altar.bits) && gold()==before && food()==0 && !identity->revivalBuilding && value("cancelled")==1,"Cancel did not refund, clear link or release food");require(session.queueRevival(backup.bits,hero.bits),"Unable to queue provider removal case");call("RemoveUnit",{backup});require(gold()==before && food()==0 && !identity->revivalBuilding && value("cancelled")==2,"Removed altar retained hero reservation or payment");++passed;std::cout<<"PASS cancellation_and_provider_removal\n";
        require(session.queueRevival(altar.bits,hero.bits),"Unable to queue ownership case");auto p1=call("Player",{vm.integer(1)});call("SetUnitOwner",{hero,p1,vm.boolean(false)});require(identity->owner==1 && !identity->revivalBuilding && session.units().at(altar.bits)->production.empty() && gold()==before && food()==0 && value("cancelled")==3,"Hero transfer left old player's queue/resources");auto location=call("Location",{vm.real(jass::Real::fromInteger(64)),vm.real(jass::Real::fromInteger(64))});require(call("ReviveHeroLoc",{hero,location,vm.boolean(false)}).bits && identity->experience==experience && identity->inventory==inventory && value("finished")==2,"Script revive did not preserve transferred hero or dispatch finish");call("RemoveLocation",{location});require(call("GetRevivingUnit",{}).bits==0 && call("GetRevivableUnit",{}).bits==0,"Hero event context leaked to host");++passed;std::cout<<"PASS transferred_hero_and_script_revive\n";
        auto count=session.units().size();require(!aiCall("SetProduce",{ai.integer(1),ai.integer(int(identity->type)),ai.integer(-1)}).bits && session.units().at(altar.bits)->production.empty(),"Campaign AI created a new hero when disabled");aiCall("SetNewHeroes",{ai.boolean(true)});require(aiCall("SetProduce",{ai.integer(1),ai.integer(int(identity->type)),ai.integer(-1)}).bits && session.units().size()==count && session.units().at(altar.bits)->production.size()==1 && !session.units().at(altar.bits)->production.front().revival,"Enabled AI hero purchase bypassed the paid train queue");++passed;std::cout<<"PASS ai_existing_hero_and_new_hero_policy\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed="<<passed<<" failed=0\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
